do $$ declare sh uuid; cat uuid; it uuid; begin select id into sh from shops order by created_at limit 1; select id into cat from categories where shop_id=sh and name='Sports Shoes'; insert into items(shop_id,name,article_no,category_id,default_price,cost_price) values(sh,'Runner Pro','SP101',cat,1499,850), (sh,'Street Classic','SP102',cat,1299,700), (sh,'Kids Flex','KD201',(select id from categories where shop_id=sh and name='Kids PU'),899,450) on conflict(shop_id,article_no) do nothing; for it in select id from items where shop_id=sh and article_no in ('SP101','SP102','KD201') loop perform add_stock(sh,it,'Black','7',2,'Sample opening stock'); perform add_stock(sh,it,'Black','8',2,'Sample opening stock'); end loop; end $$;
