insert into public.shops(name) select 'Shop 1' where not exists(select 1 from public.shops);
insert into public.categories(shop_id,name) select s.id,c.name from public.shops s cross join (values('Fancy'),('Gents PU'),('Ladies PU'),('Kids PU'),('Shoes'),('Sandals'),('Slippers'),('Sports Shoes')) c(name) on conflict(shop_id,name) do nothing;
